package com.cinebook.dashboard;
import com.cinebook.auth.*;import com.cinebook.catalog.*;import com.cinebook.common.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.cache.annotation.CacheEvict;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')")
public class AdminController {
 private final UserRepository users;private final MovieRepository movies;private final AuditService audit;private final AuditEventRepository audits;
 public AdminController(UserRepository u,MovieRepository m,AuditService a,AuditEventRepository au){users=u;movies=m;audit=a;audits=au;}
 public record RoleRequest(@NotNull Role role){}
 public record MovieCreate(@NotBlank @Size(max=180) String title,@NotBlank @Size(max=3000) String synopsis,@Size(max=700) String posterUrl,@Size(max=700) String backdropUrl,@Min(1) @Max(500) int durationMinutes,@NotBlank String language,@NotBlank String genres,@NotBlank String contentRating,java.time.LocalDate releaseDate,@DecimalMin("0.0") @DecimalMax("10.0") double rating){}
 @GetMapping("/users") public List<AuthDtos.UserView> users(){return users.findAll().stream().map(u->new AuthDtos.UserView(u.getId(),u.getEmail(),u.getDisplayName(),u.getRole().name())).toList();}
 @PatchMapping("/users/{id}/role") public AuthDtos.UserView role(java.security.Principal actor,@PathVariable Long id,@Valid @RequestBody RoleRequest r,@RequestHeader(value="X-Correlation-ID",required=false) String cid){UserAccount u=users.findById(id).orElseThrow(()->new ApiException(404,"USER_NOT_FOUND","User was not found"));if(u.getEmail().equalsIgnoreCase(actor.getName())&&r.role()!=Role.ADMIN)throw new ApiException(409,"SELF_DEMOTION_BLOCKED","Cannot remove your own administrator role");Role old=u.getRole();u.setRole(r.role());audit.record(actor.getName(),"USER_ROLE_CHANGED","USER",id.toString(),old+" -> "+r.role(),cid);return new AuthDtos.UserView(u.getId(),u.getEmail(),u.getDisplayName(),u.getRole().name());}
 @CacheEvict(value="movies",allEntries=true) @PostMapping("/movies") public CatalogDtos.MovieView createMovie(java.security.Principal p,@Valid @RequestBody MovieCreate r,@RequestHeader(value="X-Correlation-ID",required=false) String cid){Movie m=movies.save(new Movie(r.title(),r.synopsis(),r.posterUrl(),r.backdropUrl(),r.durationMinutes(),r.language(),r.genres(),r.contentRating(),r.releaseDate(),r.rating()));audit.record(p.getName(),"MOVIE_CREATED","MOVIE",m.getId().toString(),m.getTitle(),cid);return CatalogDtos.movie(m);}
 @CacheEvict(value="movies",key="#id") @PatchMapping("/movies/{id}/active") public CatalogDtos.MovieView active(java.security.Principal p,@PathVariable Long id,@RequestParam boolean active,@RequestHeader(value="X-Correlation-ID",required=false) String cid){Movie m=movies.findById(id).orElseThrow(()->new ApiException(404,"MOVIE_NOT_FOUND","Movie was not found"));m.setActive(active);audit.record(p.getName(),"MOVIE_ACTIVE_CHANGED","MOVIE",id.toString(),"active="+active,cid);return CatalogDtos.movie(m);}
 @GetMapping("/audit") public List<Map<String,Object>> audits(){return audits.findTop200ByOrderByCreatedAtDesc().stream().map(e->Map.<String,Object>of("id",e.getId(),"actor",e.getActor()==null?"system":e.getActor().getEmail(),"action",e.getAction(),"targetType",e.getTargetType(),"targetId",e.getTargetId()==null?"":e.getTargetId(),"details",e.getDetails()==null?"":e.getDetails(),"createdAt",e.getCreatedAt(),"correlationId",e.getCorrelationId()==null?"":e.getCorrelationId())).toList();}
}
